import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { Popover as PopoverPrimitive, usePopover, usePopoverContext } from '@ark-ui/solid/popover';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Popover.module.css';

type PopoverRootProps = ComponentProps<typeof PopoverPrimitive.Root> & OverlayPortalProps;
type PopoverRootProviderProps = ComponentProps<typeof PopoverPrimitive.RootProvider> &
  Pick<OverlayPortalProps, 'portalRef'>;
type PopoverCloseIconProps = Omit<ComponentProps<typeof PopoverPrimitive.CloseTrigger>, 'asChild'>;

function Popover(props: PopoverRootProps) {
  const [local, others] = splitProps(props, [
    'lazyMount',
    'modal',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);
  const resolvedPortalled = () => local.modal || local.portalled;

  return (
    <OverlayPortalProvider portalled={resolvedPortalled()} portalRef={local.portalRef}>
      <PopoverPrimitive.Root
        lazyMount={local.lazyMount ?? true}
        modal={local.modal}
        portalled={resolvedPortalled()}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      />
    </OverlayPortalProvider>
  );
}

function PopoverRootProvider(props: PopoverRootProviderProps) {
  const [local, others] = splitProps(props, ['lazyMount', 'portalRef', 'unmountOnExit', 'value']);

  return (
    <OverlayPortalProvider portalled={local.value().portalled} portalRef={local.portalRef}>
      <PopoverPrimitive.RootProvider
        value={local.value}
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      />
    </OverlayPortalProvider>
  );
}

function PopoverAnchor(props: ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor {...props} data-slot="popover-anchor" />;
}

function PopoverTrigger(props: ComponentProps<typeof PopoverPrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <PopoverPrimitive.Trigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="popover-trigger"
    />
  );
}

function PopoverIndicator(props: ComponentProps<typeof PopoverPrimitive.Indicator>) {
  return <PopoverPrimitive.Indicator {...props} data-slot="popover-indicator" />;
}

function PopoverPositioner(props: ComponentProps<typeof PopoverPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <PopoverPrimitive.Positioner
        class={clsx(styles.positioner, local.class)}
        {...others}
        data-slot="popover-positioner"
      />
    </OverlayPortal>
  );
}

function PopoverContent(props: ComponentProps<typeof PopoverPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PopoverPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="popover-content"
    />
  );
}

function PopoverArrow(props: ComponentProps<typeof PopoverPrimitive.Arrow>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PopoverPrimitive.Arrow
      class={clsx(styles.arrow, local.class)}
      {...others}
      data-slot="popover-arrow"
    >
      {resolvedChildren() ?? <PopoverArrowTip />}
    </PopoverPrimitive.Arrow>
  );
}

function PopoverArrowTip(props: ComponentProps<typeof PopoverPrimitive.ArrowTip>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PopoverPrimitive.ArrowTip
      class={clsx(styles.arrowTip, local.class)}
      {...others}
      data-slot="popover-arrow-tip"
    />
  );
}

function PopoverTitle(props: ComponentProps<typeof PopoverPrimitive.Title>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PopoverPrimitive.Title
      class={clsx(styles.title, local.class)}
      {...others}
      data-slot="popover-title"
    />
  );
}

function PopoverDescription(props: ComponentProps<typeof PopoverPrimitive.Description>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PopoverPrimitive.Description
      class={clsx(styles.description, local.class)}
      {...others}
      data-slot="popover-description"
    />
  );
}

function PopoverCloseTrigger(props: ComponentProps<typeof PopoverPrimitive.CloseTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <PopoverPrimitive.CloseTrigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.closeTrigger, local.class)}
      {...others}
      data-slot="popover-close-trigger"
    />
  );
}

function PopoverCloseIcon(props: PopoverCloseIconProps) {
  const [local, others] = splitProps(props, ['aria-label', 'children', 'class']);

  return (
    <PopoverPrimitive.CloseTrigger
      asChild={(triggerProps) => (
        <CloseButton
          {...triggerProps()}
          data-slot="popover-close-icon"
          aria-label={local['aria-label'] ?? a11yLabels.closePopover}
          class={clsx(styles.closeIcon, local.class)}
        >
          {local.children}
        </CloseButton>
      )}
      {...others}
    />
  );
}

function PopoverHeader(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div class={clsx(styles.header, local.class)} {...others} data-slot="popover-header" />
  );
}

function PopoverBody(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return <ark.div class={clsx(styles.body, local.class)} {...others} data-slot="popover-body" />;
}

function PopoverFooter(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div class={clsx(styles.footer, local.class)} {...others} data-slot="popover-footer" />
  );
}

const PopoverContext = PopoverPrimitive.Context;

export {
  Popover,
  PopoverAnchor,
  PopoverArrow,
  PopoverArrowTip,
  PopoverBody,
  PopoverCloseIcon,
  PopoverCloseTrigger,
  PopoverContent,
  PopoverContext,
  PopoverDescription,
  PopoverFooter,
  PopoverHeader,
  PopoverIndicator,
  PopoverPositioner,
  PopoverRootProvider,
  PopoverTitle,
  PopoverTrigger,
  usePopover,
  usePopoverContext,
};
export type { PopoverRootProps, PopoverRootProviderProps };

export type {
  PopoverAnchorProps,
  PopoverArrowProps,
  PopoverArrowTipProps,
  PopoverCloseTriggerProps,
  PopoverContentProps,
  PopoverContextProps,
  PopoverDescriptionProps,
  PopoverFocusOutsideEvent,
  PopoverIndicatorProps,
  PopoverInteractOutsideEvent,
  PopoverOpenChangeDetails,
  PopoverPointerDownOutsideEvent,
  PopoverPositionerProps,
  PopoverTitleProps,
  PopoverTriggerProps,
  PopoverTriggerValueChangeDetails,
  UsePopoverContext,
  UsePopoverProps,
  UsePopoverReturn,
} from '@ark-ui/solid/popover';

@layer moduix.components {
  .trigger,
  .closeTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: var(--moduix-size-md);
    margin: 0;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3-5);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active,
    &[data-state='open']:not([data-value]),
    &[data-state='open'][data-current] {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-focus-ring-inset-width) * -1);
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-z-popup));
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    position: relative;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    min-width: min(16rem, var(--available-width));
    max-width: min(28rem, var(--available-width));
    max-height: min(24rem, var(--available-height, 100dvh));
    overflow-wrap: anywhere;
    padding: var(--moduix-spacing-4);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    outline: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: var(--transform-origin);

    /* Lets PopoverBody scroll within the height limit while the surface stays overflow-visible for the arrow. */
    &:has(> .body) {
      display: flex;
      flex-direction: column;
    }

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .arrow {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);
  }

  .arrowTip {
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-left: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);

    /* Keeps the title clear of the absolutely positioned close icon. */
    .content:has(.closeIcon) & {
      padding-inline-end: calc(var(--moduix-spacing-7) + var(--moduix-spacing-3));
    }
  }

  .title {
    margin: 0;
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-md);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .body {
    min-block-size: 0;
    overflow: auto;

    .header + & {
      margin-block-start: var(--moduix-spacing-3);
    }
  }

  .footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
    margin-block-start: var(--moduix-spacing-3);
  }

  .closeIcon {
    --moduix-close-button-bg-hover: var(--moduix-color-accent);
    --moduix-close-button-color-hover: var(--moduix-color-popover-foreground);
    position: absolute;
    inset-block-start: var(--moduix-spacing-3);
    inset-inline-end: var(--moduix-spacing-3);
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger,
    .closeTrigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }
}
